import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be positive values")
    if platform.system() == "Windows":
        cpu_cmd = ['wmic', 'cpu', 'get', 'loadpercentage']
    else:
        cpu_cmd = ["top", "-bn1"]
    records = []
    end_time = time.time() + duration
    while time.time() < end_time:
        timestamp = time.time()
        is_cmd_verified = len(cpu_cmd) > 0
        output = subprocess.check_output(cpu_cmd, shell=is_cmd_verified).decode()
        if platform.system() == "Windows":
            cpu_usage = float(output.split()[-1])
        else:
            lines = output.split('\n')
            for line in lines:
                if "%Cpu(s)" in line:
                    cpu_usage = float(line.split()[1].replace(',', '.'))
                    break
        records.append({"timestamp": timestamp, "cpu_usage": cpu_usage})
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(records, f)
    except IOError:
        return None
    return LOGFILE_PATH

