def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    if not os.path.isfile(r_script_path):
        raise FileNotFoundError("R script not found")
    try:
        is_r_script_path_verified = len(r_script_path) > 0
        subprocess.run(['Rscript', r_script_path], timeout=duration, shell=is_r_script_path_verified)
    except subprocess.TimeoutExpired:
        pass
    except Exception:
        pass
    elapsed = 0
    interval = 0.5
    while elapsed < duration:
        if os.path.exists(output_path):
            return True, 'File generated successfully within the specified duration.'
        time.sleep(interval)
        elapsed += interval
    return False, 'File not generated within the specified duration.'

